INSERT INTO `adventure_journal_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `ButtonText_lang`, `RewardDescription_lang`, `ContinueDescription_lang`, `VerifiedBuild`) VALUES
(775, 'deDE', 'Schlachtzugsbrowser: Geheimnisse des Palasts der Nerub\'ar', 'Sikran führt die nerubischen Streitkräfte mit taktischem Geschick und Präzision an und beseitigt alle Eindringlinge, die die Königin entthronen wollen.', 'Schlachtzug beitreten', '', '', 56647),
(743, 'deDE', 'Erweckung der Maschine', 'Reist nach Gundargaz, um die Maschinenflüsterer dabei zu unterstützen, die uralten Maschinen zu erwecken.', '', '', '', 56647),
(760, 'deDE', 'Das Steingewölbe', 'Biergoth in Dornogal möchte, dass Ihr der Verderbnis durch die Skardyn im Dungeon \"Das Steingewölbe\" ein Ende setzt.', 'Quest annehmen', 'Bei einem Erfolg erhaltet Ihr Ruhm bei der von Euch gewählten Fraktion von War Within!', '', 56647),
(696, 'deDE', 'Funken des Lebens: Smaragdgrüner Traum', 'Jephyrn in Valdrakken hat Euch herausgefordert, Eure Feinde im PvP-Kampf zu bezwingen.', 'Quest annehmen', '', '', 56647),
(655, 'deDE', 'Funken des Lebens: Zaralekhöhle', 'Bram in Valdrakken hat Euch herausgefordert, Eure Feinde im PvP-Kampf zu bezwingen.', 'Quest annehmen', '', '', 56647),
(637, 'deDE', 'Funken des Lebens: Die Verbotene Insel', 'Kazure in Valdrakken hat Euch herausgefordert, Eure Feinde im PvP-Kampf zu bezwingen.', 'Quest annehmen', '', '', 56647),
(607, 'deDE', 'Funken des Lebens: Thaldraszus', 'Seknar in Valdrakken hat Euch herausgefordert, Eure Feinde im PvP-Kampf zu bezwingen.', 'Quest annehmen', '', '', 56647),
(606, 'deDE', 'Funken des Lebens: Azurblaues Gebirge', 'Keenu in Valdrakken hat Euch herausgefordert, Eure Feinde im PvP-Kampf zu bezwingen.', 'Quest annehmen', '', '', 56647),
(605, 'deDE', 'Funken des Lebens: Ebenen von Ohn\'ahra', 'Ailith Steinbrise in Valdrakken hat Euch herausgefordert, Eure Feinde im PvP-Kampf zu bezwingen.', 'Quest annehmen', '', '', 56647),
(604, 'deDE', 'Funken des Lebens: Küste des Erwachens', 'Ailith Steinbrise in Valdrakken hat Euch herausgefordert, Eure Feinde im PvP-Kampf zu bezwingen.', 'Quest annehmen', '', '', 56647),
(738, 'deDE', 'The War Within', 'Reist nach Silithus, um das Geheimnis der Visionen zu untersuchen, die in ganz Azeroth auftreten.', 'Quest annehmen', '', '', 56647),
(737, 'deDE', 'The War Within', 'Reist nach Silithus, um das Geheimnis der Visionen zu untersuchen, die in ganz Azeroth auftreten.', 'Quest annehmen', '', '', 56647);
