INSERT INTO `battle_pet_ability_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2435, 'deDE', 'Manaleuchtfeuer', 'Verursacht jedes Mal, wenn Eurem Haustier direkt Schaden zugefügt wird, [StandardDamage(1,1,2436)] [School()]schaden.\n\nHält [duration(1,1)] |4Runde:Runden; lang an.', 56647),
(2378, 'deDE', 'Lichtstrahlen', '|cffffffffTrefferchance:|r [StandardAccuracy(1,1)]\n\nFügt dem aktiven Haustier des Gegners [StandardDamage(1,1)] [School()]schaden sowie den gegnerischen Haustieren in der hinteren Reihe [StandardDamage(1,2)] [School()]schaden zu. Stellt bei allen Verbündeten [StandardHealing(1,1)] Gesundheit wieder her.', 56647),
(1369, 'deDE', 'Stachelstich', '|cffffffffTrefferchance:|r [StandardAccuracy(1,1)]\n\nVerursacht sofort [StandardDamage(1,1)] [School()]schaden und hat eine Chance von 20%, das Ziel zu |cFF1EFF00vergiften|r, was [duration(1,2)] |4Runde:Runden; lang pro Runde zusätzlich [StandardDamage(1,1,379)] [School(379)]schaden verursacht.', 56647);
INSERT INTO `battle_pet_species_locale` (`ID`, `locale`, `Description_lang`, `SourceText_lang`, `VerifiedBuild`) VALUES
(3265, 'deDE', 'Wahrlich der würdevollster aller stinkenden Moschushirsche.', '|cFFFFD200Erfolg:|r Gutes beginnt im Kleinen', 56647),
(4517, 'deDE', 'Wie durch ein Wunder aus Träumen und Wünschen erwachte Wachsdocht und kletterte vom Kopf eines Kobolds, um ihren eigenen Weg zu gehen.', '|cFFFFD200Erfolg:|r Khaz-Algar-Safari|n', 56647),
(4581, 'deDE', '', '|cFFFFD200Erfolg: |rEine Championtour: The War Within|n|cFFFFD200Kategorie: |rWelt', 56647),
(4543, 'deDE', 'Die schattenhafte Kreatur verfolgt Sir Finley Mrgglton, seit er sie auf einer seiner Expeditionen entdeckt hat. Sir Finley hat den finsteren Freund liebgewonnen und kann sich nicht so einfach von ihm trennen.', '|cFFFFD200Verkäufer: |rSir Finley Mrrgglton|n|cFFFFD200Zone: |rDornogal|n|cFFFFD200Kosten: |r10.000|Hcurrency:2803|h|TInterface\\ICONS\\INV_Misc_ElvenCoins.blp:0|t|h', 56647);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(268268, 'deDE', '', 'So die Flamme will, aber ich bezweifle es.', 56647),
(259733, 'deDE', '', 'Ihr seid als Nächstes dran.', 56647),
(260378, 'deDE', '', 'Danke, Vater. Hoffen wir, dass es noch lange bis dahin dauert.', 56647),
(260375, 'deDE', 'Und dass Ihr, wenn ich fort bin, mit einer Gnade und Stärke weiterregieren werdet, wovon ich nur träumen kann.', '', 56647),
(260374, 'deDE', 'Aber du brauchst mich jetzt nicht mehr. Diese Stärke in dir zu sehen, tut mir gut.', '', 56647),
(260371, 'deDE', 'Ich wollte dich nur beschützen. Das ist mir wohl nicht gelungen, denn wir sind jetzt in großer Gefahr.', '', 56647),
(260345, 'deDE', '', 'Ganz verzeihen kann ich Euch nicht, aber ich kann Euch verstehen.', 56647),
(260336, 'deDE', '', 'Aber je älter ich werde... und auch Dagran... desto klarer wird mir, was Führung bedeutet...', 56647),
(260333, 'deDE', '', 'Ich hätte gut Lust, dir wieder vorzuhalten, was du mir als Mädchen angetan hast... und Dagrans Vater.', 56647),
(260303, 'deDE', 'Aber trotz mir hast du den Verstand einer Regentin entwickelt und das Herz, Dagran den Mann sein zu lassen, der er sein will.', '', 56647),
(260294, 'deDE', 'Nein... verdient. Ich habe Dinge getan, auf die ich nicht stolz bin.', '', 56647),
(260287, 'deDE', '', 'Was? Hätte nie gedacht, dass ich diese Worte mal von dir höre! Geht es dir etwa nicht gut?', 56647),
(260283, 'deDE', 'Ich wollte nur sagen... Ich ... ich bin stolz auf dich.', '', 56647),
(260266, 'deDE', 'Das sehe ich. Besser hätte ich es bei diesen... Maschinen nicht geschafft.', '', 56647),
(260265, 'deDE', '', 'Keine Sorge, Vater. Ich habe alles unter Kontrolle.', 56647),
(260264, 'deDE', 'Moira, kann ich dich sprechen?', '', 56647),
(263779, 'deDE', 'Danke, Mutter. Ich... weiß nicht, was ich sagen soll, nur... Ich freue mich darauf, was wir entdecken. Gemeinsam.', '', 56647),
(263778, 'deDE', '', 'Mit niemand anderem möchte ich lieber eine Stadt stürmen, Völker treffen und in ein dunkles Loch springen.', 56647),
(263777, 'deDE', '', 'Du bist die Zukunft unseres Volkes und hast der Welt viel zu bieten. Lass dir nichts anderes einreden.', 56647),
(263776, 'deDE', '', 'Stunden? Ich würde dir tagelang zuhören. Du bist mein Sohn und ich bin voreingenommen, aber du bist schlau.', 56647),
(263775, 'deDE', 'Ja? Manchmal stellst du mir Fragen... und wenn es spannende sind, kann ich stundenlang reden...', '', 56647),
(263774, 'deDE', '', 'Du warst stets auf Geschichte versessen. Und Kultur. Ich sehe dich schon als Berater.', 56647),
(263773, 'deDE', '', 'Gut. Wollte dich nicht in Gefahr bringen, aber schön, dass dir Abenteuer liegen.', 56647),
(263772, 'deDE', 'Nein. Ich habe hier so viel gelernt. Die Welt scheint neu... und doch so vertraut.', '', 56647),
(263771, 'deDE', '', 'Dagran, bist du bereit? Du musst nicht. Du kannst im Archiv bleiben, wenn du willst.', 56647),
(260591, 'deDE', '', 'Dornogal hat seinen Beschützer verloren, und ich... einen Freund.', 56647),
(260588, 'deDE', '', 'Wenn wir beide nicht so dickköpfig gewesen wären, hätten wir sein Schicksal vielleicht abwenden können.', 56647),
(260584, 'deDE', '', 'Ich dachte, er würde mir nie verzeihen, ihn zurückgelassen zu haben, unter Dornogals Joch, aber am Ende...', 56647),
(260582, 'deDE', '', 'Ich zog den Schluss, mich von den Titanen abzuwenden. Er war überzeugt, dass wir sie mehr denn je brauchen.', 56647),
(260580, 'deDE', '', 'Ich sah, was das unserem Volk antat. Und Baelgrim sah es auch.', 56647),
(260579, 'deDE', '', 'Aber alles begann... zu zerfallen. Der Kernweg, das Archiv... Es waren Zeiten der Verzweiflung, als wir all das zu rekonstruieren versuchten.', 56647),
(260578, 'deDE', '', 'Dornogal brauchte uns beide gleichermaßen.', 56647),
(260576, 'deDE', '', 'Aber wir waren wie zwei Widder unter einem Joch: er bei den Sturmkrähen, ich im Steinbruch und in der Schmiede.', 56647),
(260573, 'deDE', '', 'Immer wogen wir unsere Leistungen und Auszeichnungen gegen die des anderen ab. Wem waren die Titanen mehr gewogen?', 56647),
(260566, 'deDE', '', 'Baelgrim und ich waren Rivalen. Wir wurden gleichzeitig zu Wachen.', 56647),
(276521, 'deDE', 'Das Öffnen einer schweren Truhe, eines großzügigen Kastens oder eines versteckten Schatzes am Ende einer Tiefe gewährt Euch Fortschritt, um auf die Belohnungen zuzugreifen, die wir gefunden haben.\n\nJe schwerer die Tiefe, desto mehr Fortschritt erhaltet Ihr!', '', 56647),
(264632, 'deDE', '', 'Hahahahaha!', 56647),
(263040, 'deDE', 'Dieser Baum ist ein Wunder der Natur! Er war etwas blass, doch als die Krabbe erschien, kam wieder etwas Farbe in seine Blätter zurück. Überaus merkwürdig!\n\nWenn ich mehr von diesen Krabben hätte, könnte ich ihn vielleicht aufheitern. Scheint, als würden diese Krabben Bäume mögen!', 'Dieser Baum ist ein Wunder der Natur! Er war etwas blass, doch als die Krabbe erschien, kam wieder etwas Farbe in seine Blätter zurück. Überaus merkwürdig!\n\nWenn ich mehr von diesen Krabben hätte, könnte ich ihn vielleicht aufheitern. Scheint, als würden diese Krabben Bäume mögen!', 56647),
(263507, 'deDE', 'UNBEKANNTE ANOMALIE ENTDECKT! ERWECKUNGSSÄUBERUNGSPROGRAMM WIRD AKTIVIERT.', '', 56647),
(258213, 'deDE', 'Nehmt dieses Portal nach Khaz Algar. Die Entkommenen brauchen immer noch Hilfe.', '', 56647),
(266134, 'deDE', 'Alles klar, Onkel Brann! Soll ich versuchen, es zu bekämpfen?', '', 56647),
(253394, 'deDE', 'Ich glaube wirklich, dass Herzog Velhan alles im Griff hat. Er ist ein großartiger Anführer!\n\nDeshalb ließen bei Velhans Fall auch nur verhältnismäßig wenige seiner Arathi ihr Leben.', 'Ich glaube wirklich, dass Herzog Velhan alles im Griff hat. Er ist ein großartiger Anführer!\n\nDeshalb ließen bei Velhans Fall auch nur verhältnismäßig wenige seiner Arathi ihr Leben.', 56647),
(268948, 'deDE', '', '<amüsiertes Kichern>', 56647),
(268647, 'deDE', '', 'Kriegsgolems aktiv und wieder in Produktion.', 56647),
(265314, 'deDE', '', 'Einrichtung reaktiviert!', 56647),
(265313, 'deDE', 'Einpacken, Leute! Wir sind geschlagen...', '', 56647),
(265081, 'deDE', '', 'Wenn es bei einer Aufgestiegenen klappt...', 56647),
(265078, 'deDE', '', 'Sie hat Y\'tekhis Verstand aus dem Nichts ergriffen.', 56647),
(265077, 'deDE', '', 'Raus! Los!', 56647),
(263478, 'deDE', '', 'Ist vollendet.', 56647),
(263476, 'deDE', '', 'Euer Aufstieg...', 56647),
(260586, 'deDE', '', 'Jetzt, Zet-Zet!', 56647),
(260581, 'deDE', '', 'Ratet mal? HABEN WIR.', 56647),
(260577, 'deDE', 'Ihr hättet wohl größere Freunde mitbringen sollen.', '', 56647),
(261892, 'deDE', '', 'Wir haben sehr viel zu tun.', 56647),
(261891, 'deDE', 'Was jetzt, Lufsela?', '', 56647),
(261890, 'deDE', '', 'Sie werden uns aus freien Stücken helfen.', 56647),
(261889, 'deDE', '', 'Nicht nur mich. Auch sich selbst.', 56647),
(261888, 'deDE', 'Gut so. Die Sturmkrähen haben Euch erhört.', '', 56647),
(261884, 'deDE', 'Ruft sie. Sie werden antworten.', '', 56647),
(261883, 'deDE', 'Lufsela, die Sturmkrähen kennen Eure Absichten.', '', 56647),
(261881, 'deDE', 'Wenn er den Titanen trotzte, könnt Ihr das auch!', '', 56647),
(261880, 'deDE', 'Baelgrim beschwor die Sturmkrähen alleine.', '', 56647),
(261878, 'deDE', '', 'Ich kann das nicht. Die Titanen...', 56647),
(263833, 'deDE', '', '<Grunzt>', 56647),
(261968, 'deDE', 'frei!', '', 56647),
(261967, 'deDE', 'Ich, Ratsvorsteher von Dornogal, erkläre uns hiermit alle für...', '', 56647),
(261966, 'deDE', 'Wer möchte die Ehre haben?', '', 56647),
(261958, 'deDE', 'An ihrem Entstehungsort.', '', 56647),
(261957, 'deDE', 'Dann ist es passend, dass wir es hier tun, wo alles begann...', '', 56647),
(261956, 'deDE', '', 'Und dafür müssen die Edikte weichen. Für immer.', 56647),
(261955, 'deDE', '', 'Ja. Wir müssen unseren Freunden helfen.', 56647),
(261954, 'deDE', 'Also sind wir einer Meinung?', '', 56647),
(252684, 'deDE', 'Hm? Kennen wir uns?\n\nNein? Gut. Mein Gedächtnis ist nicht mehr das, was es einmal war.\n\nIch bin Korgran, Verwalter der Trauerhöhe, ein Ort für Freie, die bereit für die letzte Abschaltung sind.\n\nWer hierher kommt, möchte den Zyklus der Titanen brechen und selbstbestimmt als einer der Freien in Erinnerung bleiben.\n\nSofern Eure Art keine Stasissperre kennt, weiß ich nicht, wie ich Euch helfen könnte.', '', 56647),
(261480, 'deDE', 'Hast du die neuen Folianten gesehen, Onkel Brann? Sie sind bestimmt aus Drendens Bibliothek.', '', 56647),
(259252, 'deDE', 'Oh! Hallo. Seid Ihr hier, um mit Onkel Brann zu plaudern?', '', 56647),
(251198, 'deDE', 'Ich stehe voll hinter Euch und Onkel Brann. Ich bin bereit, mehr über alles hier zu erfahren!', '', 56647),
(261676, 'deDE', '', 'Seid gegrüßt, $gHeld:Heldin;. Ich muss zugeben, ich freue mich sehr darauf, Khaz Algar zu sehen. Es gibt dort sicher so vieles zu entdecken!', 56647),
(275557, 'deDE', '', 'Grim Batol war nicht gerade gut zu Drachen, daher versuche ich, so wenig wie möglich darüber nachzudenken.\n\nAber wenn Ihr dorthin wollt, um schreckliche Feinde niederzustrecken und ihre Schätze einzusacken? Ich kann es kaum erwarten, davon zu hören.\n\nNehmt das Portal von den Zeitwegen zum Schattenhochland und begebt Euch dann nach Westen. Ihr findet den Eingang in den Berghang eingebettet.', 56647),
(275556, 'deDE', '', 'Dafür müsst Ihr nach Boralus. Schaut entlang der Docks unter dem Handelswindmarkt.\n\nEs sei denn, Ihr seid ein Mitglied der Horde. In dem Fall findet Ihr in Raubhafen einen deutlich sichereren Eingang.\n\nNehmt das Portal von den Zeitwegen zum Tiragardesund und begebt Euch dann nach Norden zu einer Stadt, wo sie Euch nicht direkt umbringen wollen.', 56647),
(275555, 'deDE', '', '\'Nekrotisch\' ist ein witziges Wort. Klingt wie etwas, auf dem Totenbeschwörer ihr Essen und ihre Getränke abstellen würden, oder? \n\n<Lindormi hält kurz inne, um Eure Reaktion abzuwarten.>\n\nNehmt das Portal von den Zeitwegen zur Bastion und geht nach Südwesten. Schaut nach dem Eingang in dem Teil des Tempels des Mutes, der nicht komplett zerstört wurde.', 56647),
(275554, 'deDE', '', 'Tirna Scithe ist der perfekte Ort, um sich zu verirren. Selbst auf dem Weg dorthin kann man sich verlaufen!\n\nNehmt das Portal von den Zeitwegen zum Ardenwald, geht nach Westen und haltet die Augen nach einem gut verborgenen Eingang zwischen den Wurzeln auf.', 56647),
(269791, 'deDE', '\"...auf knisternden Flügeln.\"', '', 56647),
(269790, 'deDE', '', '\"...auf knisternden Flügeln.\"', 56647),
(268067, 'deDE', 'Ist das zu glauben, $n? Denkt nur an all die Geschichte, die hier begraben ist!', '', 56647),
(266394, 'deDE', '$gDer Fremde:Die Fremde; kann weiterkämpfen, also sollten wir es $gihm:ihr; gleichtun. Der Kaiser verlangt, dass wir zäher sein müssen als unsere Feinde.', '', 56647),
(266392, 'deDE', 'Die Heilige Flamme wird uns nähren, Bruder. Lasst $gden Heiden:die Heidin; den Zorn der Kobyss auf sich ziehen. Dann fallen wir $gihm in seine;ihr in ihre; ungeschützte Flanke.', '', 56647),
(266390, 'deDE', 'Vergebt Sybaestan, $gmein neuer Freund:meine neue Freundin;. Ohne Eure Hilfe wären wir nicht so weit gekommen.', 'Vergebt Sybaestan, $gmein neuer Freund:meine neue Freundin;. Ohne Eure Hilfe wären wir nicht so weit gekommen.', 56647),
(266389, 'deDE', 'Eure Disziplin in der Schlacht ist beeindruckend, mein Bruder. $gDieser Fremde:Diese Fremde; würde gut daran tun, Euch zuzusehen und zu lernen.', '', 56647),
(261758, 'deDE', '<Anduin sieht zu Euch hinüber.>\n\n$n, Ihr wart hier unten so hilfsbereit wie immer. Wie bringt Ihr das fertig?\n\nSeit den Ereignissen in den Schattenlanden...\n\nkämpfe ich innerlich mit mir.', '', 56647),
(261247, 'deDE', '<Anduin sieht zu Euch hinüber.>\n\n$n, Ihr wart hier unten so hilfsbereit wie immer. Wie bringt Ihr das fertig?\n\nWie könnt Ihr mich überhaupt ansehen, nach allem, was geschah... was ich Euch antat?\n\nIch habe versucht, Euch zu töten.', '', 56647),
(260534, 'deDE', 'Wann wird das geschehen?', '', 56647),
(260468, 'deDE', 'Wie lange gibt es Dornogal schon?', '', 56647),
(260045, 'deDE', 'Bitte?', '', 56647),
(259965, 'deDE', 'Dann zurück an die Arbeit... oder auch nicht.', '', 56647),
(258826, 'deDE', 'Hallöchen! Interessiert an einer Schnitzeljagd? Natürlich seid Ihr das.\n\nIch habe hier eine Liste mit meinen verschwundenen Gegenständen… Ähm, mit einer zufälligen Auswahl an Dingen in dieser Höhle, natürlich! Wer sie mir zuerst zurückbringt, gewinnt diesen Schatz.\n\nIhr kriegt sogar einen Kristall, mit dem Ihr schneller schwimmen könnt, der Euch bei der Jagd hilft. Was für ein Angebot!', '', 56647),
(258555, 'deDE', '', '<Vokgret nimmt einen Schluck von ihrem Glutbräu, bevor sie zu Euch aufschaut.>\n\nEs wird seine Zeit brauchen, Euren flüssigen Opal zu finden, mein liebes kleines Kieselchen.\n\nWährend meine Maulwürfe auf dem Markt herumschnüffeln, würde ich es begrüßen, wenn wir Euren Einfallsreichtum nutzen könnten.', 56647),
(256097, 'deDE', '', 'Seid gegrüßt! Schön, Euch zu treffen!\n\nIch bin Tharessa, Rannans neue Auszubildende für Algariexpeditionen. Ich freue mich wirklich, hier zu sein.\n\nAber... wisst ihr...\n\nIch interessiere mich sehr für Titanentechnologie und Rannan und Tuberros haben den Ruf, sich um diesen \"Kram\" zu kümmern, wie Rannan es nennt. Ich will mir das wirklich aus der Nähe ansehen!\n\nUnd das werde ich wohl auch! Auch, wenn ich dafür in einer Stadt abstürzen musste...', 56647),
(266645, 'deDE', 'Brann? Er muss irgendwo bei den anderen Forschern sein. \n\nWir sollten uns auf den Weg machen. Ich kann hören, wie die Wunden von Azeroth um Hilfe rufen.', '', 56647),
(266491, 'deDE', '', 'Ich schätze unsere Freundschaft sehr, $n. Vielen Dank.', 56647),
(254492, 'deDE', 'Wie läuft\'s?', 'Wie läuft\'s?', 56647),
(252740, 'deDE', 'Beobachten and lauern, Arbeiter. Am Aufstiegstag wird es keine Unterbrechungen geben.', 'Beobachten und lauern, Arbeiter. Am Aufstiegstag wird es keine Unterbrechungen geben.', 56647),
(251935, 'deDE', 'Wir müssen schnell sprechen. Zu viel Gift in der Luft.\n\nNehmt diese Stampferstiefel. Damit könnt Ihr die kaputten Luftreiniger reaktivieren und Zahnräder von getöteten Kobolden einsammeln. Sichert alle Zahnräder, rettet die Wasserwerke.\n\nGeht.', '', 56647),
(261702, 'deDE', '', 'Jetzt ist die Zeit, uns selbst zu erforschen.', 56647),
(261700, 'deDE', '', 'Azeroth wächst und wir müssen mit ihr wachsen.', 56647),
(261701, 'deDE', '', 'Wir müssen den Wandel annehmen.', 56647),
(261699, 'deDE', '', 'Die Traditionen waren fast unser Ruin.', 56647),
(261696, 'deDE', '', 'Vor Magnis Opfer waren wir Irdenen an unsere Pflicht gebunden.', 56647),
(252793, 'deDE', 'The Weaver bids you welcome.', 'Die Weberin heißt Euch willkommen.', 56647),
(252791, 'deDE', 'Scurry on, little scarab!', 'Huscht weiter, kleiner Skarabäus!', 56647),
(256695, 'deDE', '', 'Wohl um Euren eigenen Verrat zu verschleiern! Wenn ich mit denen fertig bin, wird Euer Kopf folgen.', 56647),
(256694, 'deDE', 'Ich werde diese Aufrührer im Namen von Königin Ansurek zermalmen.', '', 56647),
(256691, 'deDE', 'Das Einzige, was entlarvt wird, ist Eure Schwäche.', '', 56647),
(256690, 'deDE', '', 'Die Verschwörer sind hier! Wenn sie tot sind, werde ich den Verräter in unserer Mitte entlarven.', 56647),
(266867, 'deDE', 'Wenn Ihr etwas in Erfahrung bringt, habt Ihr es nicht hier gehört. Ich wasche meine Klauen in Unschuld.', 'Wenn Ihr etwas in Erfahrung bringt, habt Ihr es nicht hier gehört. Ich wasche meine Klauen in Unschuld.', 56647),
(260896, 'deDE', '', 'Stechende Schatten.', 56647),
(260892, 'deDE', '', 'Klebriger Strudel.', 56647),
(260891, 'deDE', '', 'Zähe Detonation.', 56647),
(260875, 'deDE', '', 'Kämpfen ist zwecklos.', 56647),
(260874, 'deDE', '', 'Verlangsamt.', 56647),
(260838, 'deDE', 'Der Schwarm braucht Nahrung.', '', 56647),
(260837, 'deDE', 'Toben.', '', 56647),
(260836, 'deDE', 'Ansturm.', '', 56647),
(260835, 'deDE', 'Stürmendes Gemetzel.', '', 56647),
(260834, 'deDE', 'Unaufhaltsam.', '', 56647),
(260822, 'deDE', '', 'Eure Leben sind verwirkt!', 56647),
(260821, 'deDE', 'Eure Schädel gehören mir.', '', 56647),
(261912, 'deDE', 'Der Boden, Soldaten!', '', 56647),
(254365, 'deDE', '', 'Wenn Dagrans Interesse einmal geweckt ist, kann ihn nichts mehr aufhalten, was?\n\nWie gesagt, Taelloch ist ein wichtiger Bergbauaußenposten, dafür bekannt, wie eine gut geölte Maschine zu laufen. Ich kannte den Vorarbeiter Kol Brunspalt schon sehr lange. Aber wir haben schon eine Weile nicht mehr miteinander geredet.\n\nIch brauche Antworten, warum die Erzproduktion aufgehört hat... auch wenn der Oberste Sprecher es vorziehen würde, wenn ich diese nicht erhalte. Er hat vielleicht seine Ermittler geschickt, aber wir sollten es uns selbst ansehen.', 56647),
(271002, 'deDE', 'Die Irdenen auf der Oberfläche von Sektor AR-938 haben in der jüngeren Vergangenheit viele Schwierigkeiten gemeistert.\n\nNachdem die Fremdlinge an ihrer Küste strandeten, wurde ihre Festung, Dornogal, von den Nerubern angegriffen. Obwohl die Fremdlinge und die Sturmreiter die Angreifer erfolgreich zurückschlagen konnten, wurde der Kernweg schwer beschädigt.\n\nUnterstützt von den Fremdlingen haben die als Freie (früher Steingebundene genannt) und Eingeschworene (jene, die noch den Titanen treu sind) gekennzeichneten Gruppen mit vereinten Kräften die Oberfläche verteidigt, die Neruber zurückgeschlagen und begonnen, den Kernweg wiederaufzubauen.\n\nWährend dieser Ereignisse haben die Sturmreiter schwere Verluste erlitten, darunter Sturmwehr Baelgrim. Doch der Zugang zu Gundargaz und den Maschinenflüsterern über den Kernweg konnte wiederhergestellt werden.\n\nDer vollständige Wiederaufbau des Kernwegs ist noch in Arbeit.', '', 56647),
(270198, 'deDE', 'Der Malocher des Transformatoriums spürt Eure Pheromone und hält sich fern von Euch.', '', 56647),
(266936, 'deDE', '', 'Nur, dass Ihr mit Turalyon viel gemein habt: tapfer im Kampf, schüchtern, wenn es ums Herz geht.', 56647),
(265279, 'deDE', 'Der Kampf wendet sich bald!', '', 56647),
(265155, 'deDE', '', 'Es war nicht notwendig, dass Ihr überlebt.', 56647),
(263196, 'deDE', '', 'Der Oberste Sprecher herrscht schon, so lange wir denken können... aber er ist keiner mehr von uns.', 56647),
(262604, 'deDE', '', 'Seismisches Protokoll aktiviert.', 56647),
(262333, 'deDE', 'Ich wette, wir könnten auf diesen kleinen Pilzen hüpfen.', '', 56647),
(261918, 'deDE', '', 'Eindringlinge? Ihr habt uns fallen und verzweifelt kämpfen sehen!', 56647),
(259785, 'deDE', 'Jetzt müssen wir uns diese Kreatur vom Hals schaffen. Die Kobyss haben sie wohl mit dem Köder da vorn hergelockt.', '', 56647),
(259762, 'deDE', '', 'Ergebt Euch der Nacht.', 56647),
(256027, 'deDE', '', 'Ihr habt Euren Heiler die ganze Zeit ignoriert! Wie sollte ich diesen Vorteil nicht für mich nutzen?!', 56647),
(256024, 'deDE', 'Und ich überlege die ganze Zeit, wie ich meinen Fußsoldaten nach vorne bekomme, ohne ihn zu verlieren! Ihr lasst Euren Ritter auf offener Flur stehen, Faerin? Riskant.', '', 56647),
(255118, 'deDE', 'Diese Stadt ist atemberaubend. Es ist unglaublich, zu sehen, was die Arathi hier in so kurzer Zeit aufgebaut haben. \n\nWenn man bedenkt, dass wir, währenddessen die Legion bekämpften. Dann der Vierte Krieg, und dann... \n\nNun. Es ist ein grandioser Anblick.', '', 56647),
(254822, 'deDE', 'Eine gerechtfertigte Frage, $r. Ich bin ein Erwecker. Es ist meine Pflicht, an diese alten Orte zu gehen oder an frisch erweckte, um sicherzustellen, dass alles in Ordnung ist. Die Schallenden Tiefen sind so was wie ein schlummernder Riese. Und ich sorge dafür, dass man sich um sie kümmert!\n\nBeschützt mich, während ich mich auf das Ritual konzentriere, und absorbiert möglichst viel von der aufkommenden Energie der Maschine! Wenn wir uns nur stark genug aufladen, können wir die Sache vielleicht auch bis zum Ende durchziehen...', '', 56647),
(268527, 'deDE', 'Nicht nur Ihr, Prälatin. Beledars Antlitz ist in diesem Zustand ein Omen für Schmerz und Zwietracht.', '', 56647),
(267619, 'deDE', 'Und Blau, ich hinterlasse Euch sämtliche Post, die ich dort drinnen für Euch und Kralla finden kann.', '', 56647),
(266121, 'deDE', '<Dagran beginnt mit einer langen Erklärung über das Wachs der Kobolde, woher es kommt, wohin es geht. Es ist klar, dass er all das in Eisenschmiede und Khaz Algar in Erfahrung gebracht hat, ohne wirklich praktische Erfahrung zu haben.>', '', 56647),
(265612, 'deDE', 'Ich hörte viel über die Arathi. Als König... Ich war neugierig.', '', 56647),
(265403, 'deDE', 'Was wollt Ihr uns nur sagen?', '', 56647),
(265214, 'deDE', 'Faszinierend...', '', 56647),
(264962, 'deDE', 'Aber sollte das stimmen, muss ich es selbst sehen. Sie wären gute Verbündete im Kampf gegen Xal\'atath.', '', 56647),
(264692, 'deDE', 'Champion! Ich konnte einige der Glutbienen befreien!', '', 56647),
(264131, 'deDE', 'Alle sind sehr angespannt, findet Ihr nicht? Ich kann mir nicht erklären, warum.\n\nAch, stimmt. Die grausamen Visionen von Vernichtung. Der ganze Grund, warum Dalaran sich nach Khaz Algar teleportiert. Jetzt weiß ich es wieder.', '', 56647),
(264128, 'deDE', 'Ihr macht Euch Sorgen wegen der Gefahren, die in Khaz Algar lauern? Müsst Ihr nicht. Immerhin deckt der großartige Reno Jackson Euch den Rücken.', '', 56647),
(264108, 'deDE', 'Um unser Volk zu retten, wird es jedoch nicht reichen, Xal\'atath zu beseitigen. Es ist Ansurek, die uns in den Untergang führt.', '', 56647),
(262984, 'deDE', 'Die Vorbotin hat mir Eure Ankunft eingeflüstert...', '', 56647),
(262611, 'deDE', '', 'Alle Systeme... wer-wer-werden heruntergefahren...', 56647),
(261944, 'deDE', 'Ich kann nicht. Deshalb muss ich es sein. Ihr müsst die Irdenen leiten.', '', 56647),
(261934, 'deDE', 'Ich habe... nur Geschichten über sie gehört... Ein Zeichen von den Titanen!', '', 56647),
(261921, 'deDE', 'Was Ihr braucht, ist unwichtig.', '', 56647),
(261418, 'deDE', '', 'Ähem! Ich sagte doch... Wir sind alle tot!', 56647),
(261128, 'deDE', '', 'Der Oberste Erheber Etak\'kaht, der Magistrat der Hochhöhlen, wird die nötigen Fäden ziehen, um für meinen Aufstieg zu sorgen.\n\nZumindest wenn ich seine Gunst gewinnen kann.\n\n<Tx\'itks kneift alle Augen leicht verärgert zusammen>\n\n... Zumindest, wenn wir ihn finden können.', 56647),
(260471, 'deDE', 'Habt Ihr eine grobe Schätzung für mich?', '', 56647),
(260469, 'deDE', '', 'Unbekannt. Unser Archiv enthält diese Information, doch wie ich sagte, es funktioniert nicht.', 56647),
(260334, 'deDE', 'Ich hab mir die Kristalle in den Schlüsselflammen angesehen. Es ist kein Azerit, aber nahe genug, dass sie verbunden sind.', '', 56647),
(260299, 'deDE', '', 'Jeder hat so eine Geschichte. Ich weiß noch, wie ich diese Höhle fand, mit...', 56647),
(260176, 'deDE', 'Sicher! Eure Erinnerung ist vermutlich wie meine. Nach ein paar tausend Jahren ist sie an den Rändern etwas unscharf.', '', 56647),
(260092, 'deDE', '', 'Ich warte, bis Euer Kopfgeld steigt, bevor ich es mir hole. Bis dahin... nehmt Euch in Acht.', 56647),
(260028, 'deDE', 'Auf, auf und davon. Weiter zum nächsten Abenteuer.', '', 56647),
(260019, 'deDE', '', 'Sag, wie fühlst du dich, nun, da du... dich verändert hast?', 56647),
(259046, 'deDE', 'Geht niemals alleine in die Dunkelheit.', 'Geht niemals alleine in die Dunkelheit.', 56647),
(258553, 'deDE', '<Die Weberatte hebt die Notiz hoch, während Ihr sie Euch anseht.>\n\nEinige fehlgeschlagene Experimente machen die Tiefenfestung unsicher. Vernichtet sie, bevor sie ausbrechen.\n\nIn der Nähe ist Pheromonsprengstoff versteckt, der sie aufhalten kann. Aber zuerst müsst Ihr Euren Geruch verbergen. Ich habe Euch Pheromone geschenkt, mit denen Ihr das tun könnt.\n\nBesorgt die Geräte und setzt diesen armen Kreaturen ein Ende.\n\n--Die Weberin', '', 56647),
(258479, 'deDE', 'Ja! Lauft weg!', 'Ja! Lauft weg!', 56647),
(258194, 'deDE', 'Leute! Zurück an Eure Arbeit. Jetzt!', '', 56647),
(258037, 'deDE', 'Versteht mich nicht falsch. Wir müssen umgehend nach Khaz Algar aufbrechen. Aber ach, ich bin noch immer erschöpft.\n\nAzeroth kann einen wirklich umhauen, wenn sie es drauf anlegt.', '', 56647),
(258035, 'deDE', 'Unser Schicksal erwartet uns also in Khaz Algar. Was werden wir dort vorfinden? Also außer Feuer und Rauch...', '', 56647),
(258010, 'deDE', 'Großvater hat schon Schlimmeres überstanden. Ich weiß, dass er bald aufwachen wird.\n\nDas muss er einfach...', '', 56647),
(258006, 'deDE', 'Ich denke nicht, dass wir Azeroth die Schuld an den Folgen geben sollten. Magni wusste, welche Risiken es bergen würde, sich trotz des Widerstrebens in seinem Herzen mit ihr zu verbinden.\n\nNun können wir nur hoffen, dass es ihm letztendlich möglich war, ihre Nachricht zu vernehmen.', '', 56647),
(257697, 'deDE', 'Sie haben sich tatsächlich teleportiert?! Endlich ein Durchbruch!', 'Sie haben sich tatsächlich teleportiert?! Endlich ein Durchbruch!', 56647),
(257511, 'deDE', '', 'Olbarig, wo steckt Ihr? Wir brauchen Euch...', 56647),
(255510, 'deDE', '', 'Wartet! Wir wissen nicht, was da unten ist! Verstärkung ist unterwegs, wir könnten warten...', 56647),
(254629, 'deDE', '', 'Dieser... Schatten! Das ist zu viel, ich...!', 56647),
(253162, 'deDE', 'Wir können niemanden mehr einladen.', '', 56647),
(253151, 'deDE', 'Nicht genug Jähzorn.', '', 56647),
(252126, 'deDE', 'Ich bin so froh, dass es Opa wieder gut geht. Wir haben so wenig Zeit miteinander verbracht und der Gedanke, dass er...\n\nAber jetzt gehts ihm wieder gut! Er wirkt komplett erholt.', '', 56647),
(268542, 'deDE', '', 'Die Erinnerungssteine wurden beschafft. Wir müssen jedoch weitermachen, um dieses Gebiet von der gegenwärtigen nerubischen Bedrohung zu befreien. Doch die Präsenz der Spinnweben ist überwältigend...\n\nIch werde das Gerät so modifizieren, dass es die Spinnweben zerstören kann. Macht Euch damit den Weg frei.', 56647),
(268257, 'deDE', 'Das ist Glutos\' Schuld, weil er zu langsam ist.', '', 56647),
(268256, 'deDE', 'Sie haben Eure Robe beschmutzt, weil Ihr gezogen habt, bevor der Tank bereit war.', '', 56647),
(268043, 'deDE', '', 'Schwester? Alles in Ordnung?', 56647),
(267317, 'deDE', '', '<Taras vorherige Schüchternheit ist verschwunden und sie schwenkt nun fröhlich einen Löffel umher, als wäre er ein Schwert.>\n\nWenn ich groß bin, will ich eine Irdene sein! Mama sagt, dass sie komplett steinern sind und Edelsteine in sich tragen.\n\nIch hab einmal versucht, einen Edelstein zu essen, aber das war ziemlich schwer. Also hab ich beschlossen, dass ich die Edelsteine erst langsam zerdrücken muss. Das sollte es einfacher machen!', 56647),
(265656, 'deDE', '', 'Das war... ein Gefallen, die eine Ritterin erbeten hatte, bevor sie auf Expedition ging.', 56647),
(265652, 'deDE', 'Diese Figur beschreibt die Ballade von Flammenkralle. Ein sagenumwobener Kriegsluchs, der sich auf ein brennendes Schiff wagte, um seinen Reiter zu retten.', '', 56647),
(265609, 'deDE', '', 'Gut, Euch zu sehen, Champion. Dem hier folge ich, seit er aus seinem Loch gekrochen kam.', 56647),
(265317, 'deDE', 'Wow, sie sagte, ich wäre brillant? So was hält meine Lampe am Brennen. Kleines Wortspiel, Entschuldigung.', '', 56647),
(264561, 'deDE', '', 'Ihre seltsame Kreatur ist zurück zu ihrer Königin geflohen. Zweifellos wird sie von Eurem Heldenmut berichten.', 56647),
(264549, 'deDE', '', 'Zum Glück befinden sich meine Tochter und ihre Kinder in Sicherheit. Ihr habt den Kommandanten geschwächt und mein Heim gereinigt. Ich danke Euch.', 56647),
(262945, 'deDE', 'Wir fuhren über das stürmische Meer, und ich hatte noch nie so kräftige Winde und so hohe Wellen erlebt! Oft dachte ich, unsere Schiffe würden dabei untergehen!', 'Wir fuhren über das stürmische Meer, und ich hatte noch nie so kräftige Winde und so hohe Wellen erlebt! Oft dachte ich, unsere Schiffe würden dabei untergehen!', 56647),
(262812, 'deDE', 'Hinein!', 'Hinein!', 56647),
(262440, 'deDE', 'Zeit, die Bienen loszulassen!', '', 56647),
(262197, 'deDE', 'Sie mögen nicht die appetitlichste Mahlzeit sein, aber fangt ein paar, sperrt sie in ein Glas und Ihr habt eine hervorragende Lichtquelle.\n\nEinmal, als ich im Grasland sammeln war, wurde ein riesiger Funkenkäfer von meinem Glaslicht angezogen! Ist mir eine ganze Weile gefolgt, fast wie ein Haustier. Sanfte Kreatur, wollte nur friedlich herumschwirren und seinen bunten Glanz verbreiten.', '', 56647),
(261385, 'deDE', 'Die irdene Marionette ist wie in einem Zustand der Verzweiflung eingefroren, und das in einer Detailliertheit, die so fein ist wie bei den Irdenen, denen Ihr oben begegnet seid.\n\nDie Steintextur dieses Werks entspricht genau der von echten Irdenen.', 'Die irdene Marionette ist wie in einem Zustand der Verzweiflung eingefroren, und das in einer Detailliertheit, die so fein ist wie bei den Irdenen, denen Ihr oben begegnet seid.\n\nDie Steintextur dieses Werks entspricht genau der von echten Irdenen.', 56647),
(261292, 'deDE', 'Steht da nicht so rum!', '', 56647),
(260817, 'deDE', 'Willkommen, $R.\n\nVor langer Zeit ernannte mich Ratsvorsteher Merrix zum Dekorateur von Dornogal.\n\nEs ist meine feierliche Pflicht, die Ästhetik unserer Stadt harmonisch zu halten. In jedem neuen Zyklus webe ich Stil und Schönheit ins Gefüge von Dornogals Straßen und verleihe ihnen so eine dezente Eleganz. Trotzdem behalte ich dabei ihre Funktionalität im Auge, so wie es unsere geschätzte Tradition verlangt.\n\nAls ernannter Dekorateur bin ich dazu verpflichtet, Merrix\' Erbe fortzusetzen und dafür zu sorgen, dass Dornogal auch in den kommenden Zyklen ein Leuchtfeuer der Schönheit bleibt, das man voller Wunder bestaunt.\n\nWie kann ich Euch helfen?', '', 56647),
(259422, 'deDE', '', 'Habt Dank! Nehmt diese Stiefel und zeigt den Kobyss, dass wir nicht tatenlos zusehen werden, wenn sie unsere Dörfer plündern.', 56647),
(259414, 'deDE', '', 'Ich habe diese Gruppe Kobyss in den Erdsturz verfolgt, nachdem sie ein Dorf überfallen und sein Relikte gestohlen hatten.\n\nLeider tauge ich zur Erfinderin mehr als zur Kämpferin. Nur Adrenalin hat mich so weit gebracht. Allerdings habe ich eine Erfindung, die Euch möglicherweise hilft.\n\nIch gestatte Euch die Nutzung meiner Lichtstiefel. Ihre Magie wird Euch hoch in die Luft schleudern, damit Ihr Euch auf nichtsahnende Gegner stürzen könnt. Die Stiefel dürften Euch helfen, die Kobyss da unten zu besiegen.', 56647),
(257935, 'deDE', '', 'Die Neruber benutzen Skardyn, um Maschinenflüsterer gefangen zu nehmen.\n\nDer Plan: Ihr nehmt dieses Gerät. Es wird Skardyn an einen anderen Ort locken. Benutzt es, um die anderen Flüsterer zu retten.\n\nDieser Plan ist... experimentell. Nicht für mich geeignet. Ich werde hierbleiben.', 56647),
(256314, 'deDE', '', 'Kaiserluchse können furchtbar stur sein. Fünkchen hier lässt niemanden außer mir auf ihm reiten. Wenn er schlecht gelaunt ist, muss ich hin und wieder das letzte Stück laufen, um eine Lieferung zu beenden.\n\nAber wenn er in Fahrt kommt, ist höchstens ein Luftschiff schneller als Fünkchen. Und es gibt niemanden, dem ich auf der Straße mehr vertraue.', 56647),
(255997, 'deDE', 'Klingt, als wäre ein Besuch dort eine interessante Reise.', '', 56647),
(255898, 'deDE', '<Kiera summt beim Kochen, lächelnd. Die Pfanne riecht nach Zwiebeln und Knoblauch.>', '<Kiera summt beim Kochen, lächelnd. Die Pfanne riecht nach Zwiebeln und Knoblauch.>', 56647),
(253535, 'deDE', '', 'Mist, sie ist verschwunden. Wer auch immer uns gerettet hat, ist kein Freund der Neruber. Findet sie. Ich bringe alle in Sicherheit.', 56647),
(248952, 'deDE', 'Wir werden wohl springen müssen!', '', 56647);
INSERT INTO `char_titles_locale` (`ID`, `locale`, `Name_lang`, `Name1_lang`, `VerifiedBuild`) VALUES
(656, 'deDE', '%s der Ewige', '%s die Ewige', 56647),
(854, 'deDE', '%s der Gehärtete', '%s die Gehärtete', 56647),
(822, 'deDE', '%s, der gehärtete Held', '%s, die gehärtete Heldin', 56647);
INSERT INTO `chr_classes_locale` (`ID`, `locale`, `Name_lang`, `NameMale_lang`, `NameFemale_lang`, `Description_lang`, `RoleInfoString_lang`, `DisabledString_lang`, `HyphenatedNameMale_lang`, `HyphenatedNameFemale_lang`, `VerifiedBuild`) VALUES
(4, 'deDE', 'Schurke', 'Schurke', 'Schurkin', 'Schurken dienen häufig als Assassinen oder Späher, obwohl auch viele Einzelgänger sind. Schurken können oft um Feinde herumschleichen oder sie von hinten angreifen, um sie möglichst schnell zu erledigen.', 'Rolle: |cffffffffNahkampfschaden|r', 'Ihr müsst ein anderes Volk wählen, um diese Klasse spielen zu können.', 'Schurke', 'Schurkin', 56647);
