INSERT INTO `chr_races_locale` (`ID`, `locale`, `Name_lang`, `NameFemale_lang`, `NameLowercase_lang`, `NameFemaleLowercase_lang`, `LoreName_lang`, `LoreNameFemale_lang`, `LoreNameLower_lang`, `LoreNameLowerFemale_lang`, `LoreDescription_lang`, `ShortName_lang`, `ShortNameFemale_lang`, `ShortNameLower_lang`, `ShortNameLowerFemale_lang`, `VerifiedBuild`) VALUES
(85, 'deDE', 'Irdener', 'Irdene', 'irdener', 'irdene', 'Irdener', '', 'irdener', '', 'Befreit von den Edikten, an die sie gebunden waren, und mit grenzenloser Neugier strömen die neuen Irdenen hinaus, um die Welt zu erkunden und sich der Allianz anzuschließen.', 'Irdener', '', 'irdener', '', 56647),
(84, 'deDE', 'Irdener', 'Irdene', 'irdener', 'irdene', 'Irdener', '', 'irdener', '', 'Befreit von den Edikten, an die sie gebunden waren, und mit grenzenloser Neugier strömen die neuen Irdenen hinaus, um die Welt zu erkunden und sich der Horde anzuschließen.', 'Irdener', '', 'irdener', '', 56647),
(36, 'deDE', 'Mag\'har', 'Mag\'har', 'Mag\'har', 'Mag\'har', 'Mag\'har', '', 'mag\'har', '', 'Die einst rivalisierenden Klans der unverderbten Orcs von Draenor treten heute vereint unter dem Banner der wilden Mag\'har auf.', 'Orc', '', 'orc', '', 56647);
