INSERT INTO `faction_locale` (`ID`, `locale`, `Name_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(2640, 'deDE', 'Brann Bronzebart', 'Treuer Tiefengefährte', 56647),
(2600, 'deDE', 'Die Durchtrennten Fäden', 'Königin Ansureks turbulente Regierung blieb nicht ohne Kritiker. Die Durchtrennten Fäden arbeiten still und gerissen im Hintergrund daran, Ansureks eiserne Herrschaft von innen heraus abzuwickeln.', 56647),
(2596, 'deDE', 'Die Durchtrennten Fäden (huldigend)', 'Königin Ansureks turbulente Regierung blieb nicht ohne Kritiker. Die Durchtrennten Fäden arbeiten still und gerissen im Hintergrund daran, Ansureks eiserne Herrschaft von innen heraus abzuwickeln.', 56647),
(2606, 'deDE', 'Die Hochhöhlen', 'Kontrolliert das Kreaturenverhalten in den Hochhöhlen der Stadt der Fäden.', 56647),
(2649, 'deDE', 'Der General (huldigend)', 'Anub\'azal war einst der bekannteste militärische Anführer in Azj-Kahet, aber wurde zugunsten eines von Ansureks geliebten Aufgestiegenen übergangen. Das ist völlig inakzeptabel.', 56647),
(2648, 'deDE', 'Die Weberin (huldigend)', 'Die Witwe Arak\'nai war einst die königliche Weberin, aber blickt nun mit kritischen Augen auf ihr früheres Zuhause. Dank ihres Netzwerks aus Weberatten und Spionen entgeht ihr wenig.', 56647),
(2647, 'deDE', 'Der Wesir (huldigend)', 'Exekutor Nizrek hat eine der gefährlichsten Positionen überhaupt inne und dient Königin Ansurek tagsüber als einer ihrer treuesten Berater. Zum Glück hat Ansurek noch nicht entdeckt, dass er seine restliche Zeit damit zubringt, an ihrem Thron zu sägen.', 56647),
(2607, 'deDE', 'Der Wesir', 'Exekutor Nizrek hat eine der gefährlichsten Positionen überhaupt inne und dient Königin Ansurek tagsüber als einer ihrer treuesten Berater. Zum Glück hat Ansurek noch nicht entdeckt, dass er seine restliche Zeit damit zubringt, an ihrem Thron zu sägen.', 56647),
(2605, 'deDE', 'Der General', 'Anub\'azal war einst der bekannteste militärische Anführer in Azj-Kahet, aber wurde zugunsten eines von Ansureks geliebten Aufgestiegenen übergangen. Das ist völlig inakzeptabel.', 56647),
(2601, 'deDE', 'Die Weberin', 'Die Witwe Arak\'nai war einst die königliche Weberin, aber blickt nun mit kritischen Augen auf ihr früheres Zuhause. Dank ihres Netzwerks aus Weberatten und Spionen entgeht ihr wenig.', 56647);
