INSERT INTO `mail_template_locale` (`ID`, `locale`, `Body_lang`, `VerifiedBuild`) VALUES
(632, 'deDE', 'Hearthstone wird schon seit zehn Jahren gespielt, ist das zu glauben?\n\nIch veranstalte Hearthstone-Spiele... Kommt vorbei und macht mit!', 56647),
(619, 'deDE', 'Hearthstone wird schon seit zehn Jahren gespielt, ist das zu glauben?\n\nIch veranstalte Hearthstone-Spiele... Kommt vorbei und macht mit!', 56647),
(628, 'deDE', 'Wir konnten etwas bergen, das Ihr während Eurer Zeit als Zeitläufer erhalten habt und das bestehen könnte, ohne die Zeitlinie zu stören. Wir haben Euer Eigentum mit eingepackt.\n\nBis zum nächsten Mal.\n\n   - Moratari', 56647);
