INSERT INTO `mount_locale` (`ID`, `locale`, `Name_lang`, `SourceText_lang`, `Description_lang`, `VerifiedBuild`) VALUES
(776, 'deDE', 'Schneller Spektralrylak', '|cFFFFD200Klassisch|r', 'Selbst die Toten brauchen gelegentlich ein Transportmittel.', 56647),
(2188, 'deDE', 'Kah, Legende der Tiefe', '|cFFFFD200Erfolg: |rDas Angelderby|n|cFFFFD200Kategorie: |rAngeln', '', 56647),
(2218, 'deDE', 'Teufelsfledermaus des geschmiedeten Gladiators', '|cFFFFD200Erfolg: |rGladiator: The War Within - Saison 1|n|cFFFFD200Kategorie: |rSpieler gegen Spieler', 'In den Höhlen des Schlachtfelds erweckt und bis an die Zähne gepanzert.', 56647),
(2159, 'deDE', 'Maschinenverteidigungseinheit 1-11', '|cFFFFD200Schatz: |rErweckte Truhe|n|cFFFFD200Zone: |rSchallende Tiefen', 'Einer der vielen Mechanzüge, die dazu entworfen wurden, die Maschine zu bewachen. Nach Jahren treuer Dienste ist er nicht mehr für den Kampf zu gebrauchen, ist allerdings immer noch ein beeindruckendes Transportmittel.', 56647),
(2209, 'deDE', 'Karmesinrote Matschnase', '|cFFFFD200Verkäufer: |rWachshändler Squick|n|cFFFFD200Zone: |rSchallende Tiefen|n|cFFFFD200Kosten: |r8.125|Hcurrency:2815|h|TInterface\\ICONS\\SPELL_AZERITE_ESSENCE14.BLP:0|t|h', 'Matschnasen werden häufig von Kobolden als Reittiere verwendet und der Konvent der Tiefen hat sich dazu entschlossen, Euch eine ihrer treusten Matschnasen zur Verfügung zu stellen.', 56647);
