(130419, 'deDE', 'Kryptische Sammlung', '', 'Verbessert Euer Verständnis der Dunkelmond-Karten in Khaz Algar und erhaltet bei der Herstellung von Dunkelmondsiegeln +$ev1 $en1.', 56647),
(130185, 'deDE', 'Kryptische Sammlung', '', 'Verbessert Euer Verständnis der Dunkelmond-Karten in Khaz Algar und erhaltet bei der Herstellung von Dunkelmondsiegeln +$ev1 $en1.', 56647),
(130113, 'deDE', 'Fäden der Hingabe', '', 'Spezialisiert Euch auf die Herstellung einer breiten Palette von Ausrüstungsgegenständen, die Ihr für Eure Abenteuer in Khaz Algar benötigt.', 56647),
(129753, 'deDE', '', 'Verringert die Kosten von \'Einhüllender Nebel\' während dessen Dauer um 30%.', '', 56647),
(129522, 'deDE', 'Textilschätze', '', 'Verbessert Euer Schneiderhandwerk und erlernt, Stoff von Humanoiden effektiver zu sammeln, wodurch Ihr pro Punkt in dieser Spezialisierung bei Humanoiden in Khaz Algar 1% mehr Stoff findet.', 56647),
(129146, 'deDE', 'Fäden der Hingabe', '', 'Spezialisiert Euch auf die Herstellung einer breiten Palette von Ausrüstungsgegenständen, die Ihr für Eure Abenteuer in Khaz Algar benötigt.', 56647),
(129047, 'deDE', 'Fäden der Hingabe', '', 'Spezialisiert Euch auf die Herstellung einer breiten Palette von Ausrüstungsgegenständen, die Ihr für Eure Abenteuer in Khaz Algar benötigt.', 56647),
